func:
// Drains the in-memory handoff queue tab-dsp-iam-issuance's
// dsp-iam-issuance-vc-push pushes VC records onto. Read-then-clear
// happens synchronously in this same tick (Node-RED function nodes run
// on a single-threaded event loop, so there is no concurrent-drain race
// between this node and the next inject tick), but the queue is cleared
// BEFORE the Mongo insertMany below actually completes.
//
// ponytail: if the insertMany downstream fails (Mongo unreachable, etc.),
// the drained batch is lost rather than requeued — matches the task's
// own spec ("setting it back to [] after reading"). Acceptable for a
// best-effort persistence queue; add a requeue-on-error path if
// durability guarantees are ever needed here.
const pending = global.get('identityHubPending') || [];
if (pending.length === 0) {
    return null;
}
global.set('identityHubPending', []);

// dsp-iam-issuance-vc-push (tab-dsp-iam-issuance) hands off records shaped
// { did, kid, jti, vc, vcJwt, issuedAt, gxdch } — vc is the full nested VC
// claims object (vc.type is an array, vc.issuer/vc.credentialSubject.id are
// the DID strings). dsp-iam-hub-query-fn's buildCredentialFilter (Task 11,
// kept byte-identical to the proven spec) filters on TOP-LEVEL type/issuer/
// subject/status, none of which exist on the record as-is — so reshape each
// record into an insertable document that surfaces those 4 fields, derived
// from the nested vc claims, while keeping the original fields for audit.
//
// Also assigns an explicit string _id (the record's own jti — already a
// unique per-credential identifier) instead of leaving Mongo to generate an
// ObjectId: node-red-contrib-mongodb4's handleDocId string->ObjectId
// auto-conversion is documented in its own source as "DEPRECATED: no
// longer maintained, do not use in future projects", so this sidesteps the
// string-vs-ObjectId _id mismatch entirely instead of depending on it.
const docs = pending.map((record) => ({
    _id: record.jti,
    type: (record.vc && Array.isArray(record.vc.type) && record.vc.type.length > 0)
        ? record.vc.type[record.vc.type.length - 1]
        : 'VerifiableCredential',
    issuer: (record.vc && record.vc.issuer) || record.did,
    subject: (record.vc && record.vc.credentialSubject && record.vc.credentialSubject.id) || null,
    status: 'active',
    statusListIndex: (typeof record.statusListIndex === 'number') ? record.statusListIndex : null,
    ...record
}));

// mongodb4's operation node expects msg.payload to be an ARRAY of the
// driver call's positional arguments — insertMany(docs) takes a single
// array-of-documents argument, so payload is [docs], not docs.
msg.payload = [docs];
return msg;

// Byte-identical to buildCredentialFilter in
// orce/tests/flows/iam-hub-query-filter.spec.js (Task 11) — a NoSQL
// injection guard. Only these 4 fields are ever allowed through, and
// only when the value is a plain string (rejects object-valued injection
// attempts like ?issuer[$ne]=null, and array values like repeated
// ?type=a&type=b).
function buildCredentialFilter(queryParams) {
    const ALLOWED = ['type', 'issuer', 'subject', 'status'];
    const filter = {};
    for (const key of ALLOWED) {
        const value = queryParams && queryParams[key];
        if (typeof value === 'string' && value.length > 0) {
            filter[key] = value;
        }
    }
    return filter;
}

const filter = buildCredentialFilter(msg.req.query);

// mongodb4's operation node expects msg.payload to be an ARRAY of the
// driver call's positional arguments — find(filter) takes one argument.
msg.payload = [filter];
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// A single hardcoded key ("_id") — safe since only the id VALUE is
// client-controlled, never the key name. msg.req.params.id is never
// spread directly into the filter object. Documents get an explicit
// string _id (record.jti) at insert time (dsp-iam-hub-drain-fn), so a
// plain string match here is correct — no ObjectId conversion needed.
//
// _singleItem tags this request so dsp-iam-hub-unwrap-fn (downstream of
// the shared find node this and the list route both use) knows to unwrap
// the 0-or-1-element result array into a single object/404, instead of
// returning it as an array like the list route does.
msg._singleItem = true;
msg.payload = [{ _id: msg.req.params.id }];
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// Fixed filter — this doubles as the DCP Credential-Service pull
// endpoint counterparties call to fetch this connector's own
// self-issued Participant VC (see tab-dsp-iam-issuance's
// dsp-iam-issuance-vc-fn, which self-issues about env.get('DSP_CONNECTOR_DID')).
// 'ParticipantCredential' matches vc.type's last array entry as reshaped
// by dsp-iam-hub-drain-fn — dsp-iam-issuance-vc-fn now signs that as the
// VC's second @type entry (['VerifiableCredential', 'ParticipantCredential']).
//
// _singleItem tags this request so dsp-iam-hub-unwrap-fn (downstream of
// the shared find node this and the list route both use) knows to unwrap
// the 0-or-1-element result array into a single object/404, instead of
// returning it as an array like the list route does.
msg._singleItem = true;
msg.payload = [{ type: 'ParticipantCredential', subject: env.get('DSP_CONNECTOR_DID') }];
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// Shared by all three read routes via dsp-iam-hub-mongo-find. Only the
// single-item routes (:id and /participant) set msg._singleItem before
// reaching the shared find node — the list route (dsp-iam-hub-query-fn)
// never does, so its full result array passes through here unchanged.
if (!msg._singleItem) {
    return msg;
}
delete msg._singleItem;

const results = Array.isArray(msg.payload) ? msg.payload : [];
if (results.length === 0) {
    msg.statusCode = 404;
    msg.payload = { error: 'not found' };
} else {
    msg.payload = results[0];
    msg.statusCode = 200;
}
return msg;

// Fetch every credential's revocation-relevant fields. No client
// input reaches this query (GET has no params), so no injection
// surface — unlike dsp-iam-hub-query-fn's filter builder, this
// always queries everything.
msg.payload = [{}, { projection: { statusListIndex: 1, status: 1, _id: 0 } }];
return msg;

// Builds and self-signs a W3C BitstringStatusList credential from the
// Identity Hub's own credential-status records. 131,072 bits
// (16,384 bytes uncompressed) is the W3C-recommended minimum list
// size — chosen for privacy (a too-small list would let observers
// correlate holders by list position), not for our issuance volume,
// which is far smaller; gzip compresses an overwhelmingly-zero
// bitstring to a handful of bytes regardless of list size. Bit
// ordering (MSB-first within each byte) must stay consistent with
// dsp-iam-verify-status-list-fn's reader — both are this codebase's
// own code, so internal consistency matters more than matching any
// external implementation's convention.
const LIST_SIZE_BITS = 131072;

(async () => {
    try {
        const did = env.get('DSP_CONNECTOR_DID');
        const rawKey = env.get('DSP_CONNECTOR_KEY');
        if (!did || !rawKey) {
            node.error('[iam-hub] DSP_CONNECTOR_DID/DSP_CONNECTOR_KEY not set — cannot sign status list');
            msg.statusCode = 500;
            msg.headers = { 'Content-Type': 'application/json' };
            msg.payload = { error: 'connector identity not provisioned' };
            return node.send(msg);
        }

        const bitstring = Buffer.alloc(LIST_SIZE_BITS / 8, 0);
        const rows = Array.isArray(msg.payload) ? msg.payload : [];
        for (const row of rows) {
            if (row.status !== 'revoked') continue;
            const idx = row.statusListIndex;
            if (typeof idx !== 'number' || idx < 0 || idx >= LIST_SIZE_BITS) continue;
            const byteIdx = Math.floor(idx / 8);
            const bitIdx = 7 - (idx % 8);
            bitstring[byteIdx] |= (1 << bitIdx);
        }

        const encodedList = zlib.gzipSync(bitstring).toString('base64url');
        const kid = did + '#key-1';
        const id = 'https://' + did.split(':').slice(2).map(decodeURIComponent).join('/') + '/iam/status-list';

        const statusListVc = {
            '@context': [
                'https://www.w3.org/2018/credentials/v1',
                'https://www.w3.org/ns/credentials/status/v1'
            ],
            id: id,
            type: ['VerifiableCredential', 'BitstringStatusListCredential'],
            issuer: did,
            issuanceDate: new Date().toISOString(),
            credentialSubject: {
                id: id + '#list',
                type: 'BitstringStatusList',
                statusPurpose: 'revocation',
                encodedList: encodedList
            }
        };

        const privateJwk = typeof rawKey === 'string' ? JSON.parse(rawKey) : rawKey;
        const alg = privateJwk.alg || 'ES256';
        const key = await jose.importJWK(privateJwk, alg);
        const jwt = await new jose.SignJWT({ vc: statusListVc })
            .setProtectedHeader({ alg: alg, kid: kid, typ: 'vc+jwt' })
            .setIssuer(did)
            .setIssuedAt()
            .sign(key);

        msg.payload = { format: 'jwt_vc_json', credential: jwt };
        msg.statusCode = 200;
        msg.headers = { 'Content-Type': 'application/json' };
        node.send(msg);
    } catch (err) {
        node.error('[iam-hub] status list build failed: ' + err.message, msg);
        msg.statusCode = 500;
        msg.headers = { 'Content-Type': 'application/json' };
        msg.payload = { error: 'internal error building status list' };
        node.send(msg);
    }
})();
return null;

// Bearer shared-secret guard — same pattern and same secret as
// dsp-iam-issuance-vc-guard (tab-dsp-iam-issuance): both gate a write
// action of comparable sensitivity (issuing vs. revoking this
// connector's own credentials), so reusing DSP_OID4VCI_SHARED_SECRET
// avoids a second Helm value for an equivalent trust boundary rather
// than being an oversight.
const authHeader = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const m = /^Bearer\s+(\S+)/i.exec(authHeader.trim());
const token = m ? m[1] : null;

function reject(code, detail) {
    msg.statusCode = 401;
    msg.headers = { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' };
    msg.payload = {
        '@context': 'https://w3id.org/dspace/2025/1/context.jsonld',
        '@type': 'dspace:Error',
        'dspace:code': code,
        'dspace:reason': [detail]
    };
    return [null, msg];
}

const sharedSecret = env.get('DSP_OID4VCI_SHARED_SECRET') || '';

if (!token) {
    return reject('missing_authorization', 'Authorization: Bearer <token> header is required');
}

if (!sharedSecret) {
    node.warn('[iam-hub] DSP_OID4VCI_SHARED_SECRET not set — accepting any Bearer token (unauthenticated)');
    return [msg, null];
}

// Length check first: length is not secret, and feeding timingSafeEqual
// mismatched-length buffers throws rather than comparing.
const provided = Buffer.from(token, 'utf8');
const expected = Buffer.from(sharedSecret, 'utf8');
const matches = provided.length === expected.length && crypto.timingSafeEqual(provided, expected);

if (!matches) {
    return reject('invalid_authorization', 'Bearer token does not match configured shared secret');
}
return [msg, null];

msg._revokeId = msg.req.params.id;
msg.payload = [{ _id: msg.req.params.id }, { $set: { status: 'revoked' } }];
return msg;

// mongodb4's operation node sets msg.payload to the driver's raw
// UpdateResult for any non-find/aggregate/watch operation (confirmed
// by reading node_modules/node-red-contrib-mongodb4/src/mongodb4.js —
// same verification discipline as the rest of this tab's Mongo
// integration): { acknowledged, matchedCount, modifiedCount, ... }.
const result = msg.payload || {};
if (!result.matchedCount) {
    msg.statusCode = 404;
    msg.payload = { error: 'not found', id: msg._revokeId };
} else {
    msg.statusCode = 200;
    msg.payload = { id: msg._revokeId, status: 'revoked' };
}
delete msg._revokeId;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// mongodb4's operation node calls done(err) on failure without ever
// calling send(msg) — confirmed in its source (see
// dsp-iam-hub-revoke-result-fn's comment) — so an unhandled Mongo
// error here would otherwise leave this POST hanging until the
// ingress's 120s proxy-read-timeout fires a 504, the same class of
// bug already fixed once in tab-dsp-iam-issuance's vc-push node. This
// catch node, scoped to just dsp-iam-hub-mongo-revoke, guarantees a
// real response instead.
msg.statusCode = 502;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    '@context': 'https://w3id.org/dspace/2025/1/context.jsonld',
    '@type': 'dspace:Error',
    'dspace:code': 'internal_error',
    'dspace:reason': ['revoke operation failed: ' + (msg.error && msg.error.message)]
};
return msg;
